### Input.tsx

```tsx
import React, {
  useState,
  useEffect,
  useRef,
  KeyboardEvent,
  ChangeEvent,
  FocusEvent,
} from "react";
import { FixedSizeList as List } from "react-window";
import AutoSizer from "react-virtualized-auto-sizer";

type InputProps = {
  options: string[];
  placeholder?: string;
  onChange?: (value: string) => void;
  className?: string;
  id?: string;
};

/**
 * Input component with dropdown filtered options and validation.
 */
const Input: React.FC<InputProps> = ({
  options,
  placeholder = "",
  onChange,
  className = "",
  id,
}) => {
  const [value, setValue] = useState("");
  const [isFocused, setFocused] = useState(false);
  const [filteredOptions, setFilteredOptions] = useState<string[]>([]);
  const [showDropdown, setShowDropdown] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState<number>(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Filter options when value changes (debounce can be added for performance if needed)
  useEffect(() => {
    if (value.trim() === "") {
      setFilteredOptions([]);
      setShowDropdown(false);
      setHighlightedIndex(-1);
      return;
    }

    const filtered = options.filter((opt) =>
      opt.toLowerCase().includes(value.toLowerCase())
    );
    setFilteredOptions(filtered);
    setShowDropdown(filtered.length > 0);
    setHighlightedIndex(-1); // reset highlight when input changes
  }, [value, options]);

  // Validation: value must be one of options (case-insensitive)
  const isValid = options.some(
    (opt) => opt.toLowerCase() === value.trim().toLowerCase()
  );

  // Handle user typing
  function handleChange(e: ChangeEvent<HTMLInputElement>) {
    setValue(e.target.value);
    onChange?.(e.target.value);
  }

  // Handle keyboard navigation
  function handleKeyDown(e: KeyboardEvent<HTMLInputElement>) {
    if (!showDropdown || filteredOptions.length === 0) {
      return;
    }

    if (e.key === "ArrowDown") {
      e.preventDefault();
      setHighlightedIndex((prev) =>
        prev < filteredOptions.length - 1 ? prev + 1 : 0
      );
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlightedIndex((prev) =>
        prev > 0 ? prev - 1 : filteredOptions.length - 1
      );
    } else if (e.key === "Enter") {
      e.preventDefault();
      if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
        const selected = filteredOptions[highlightedIndex];
        setValue(selected);
        onChange?.(selected);
        setShowDropdown(false);
        inputRef.current?.blur();
      }
    } else if (e.key === "Escape") {
      setShowDropdown(false);
      setHighlightedIndex(-1);
    }
  }

  // Handle option click
  function handleOptionClick(option: string) {
    setValue(option);
    onChange?.(option);
    setShowDropdown(false);
    inputRef.current?.focus();
  }

  // Close dropdown on outside click
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setShowDropdown(false);
        setHighlightedIndex(-1);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  // Accessibility: id for list and for tying input to dropdown
  const listboxId = id ? `${id}-listbox` : undefined;

  // Size and item height for virtualization
  const ITEM_HEIGHT = 35;
  const MAX_VISIBLE_ITEMS = 6;
  const dropdownHeight = Math.min(filteredOptions.length, MAX_VISIBLE_ITEMS) * ITEM_HEIGHT;

  // Row renderer for react-window
  const Row = ({
    index,
    style,
  }: {
    index: number;
    style: React.CSSProperties;
  }) => {
    const option = filteredOptions[index];
    const isHighlighted = index === highlightedIndex;
    return (
      <div
        style={{
          ...style,
          backgroundColor: isHighlighted ? "#3399FF" : "white",
          color: isHighlighted ? "white" : "black",
          padding: "8px 12px",
          cursor: "pointer",
          borderBottom: "1px solid #ddd",
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
        }}
        role="option"
        aria-selected={isHighlighted}
        id={`${listboxId}-option-${index}`}
        key={option}
        onMouseDown={(e) => {
          // prevent input blur before onClick
          e.preventDefault();
        }}
        onClick={() => handleOptionClick(option)}
        onMouseEnter={() => setHighlightedIndex(index)}
      >
        {option}
      </div>
    );
  };

  return (
    <div
      ref={containerRef}
      className={`input-dropdown-container ${className}`}
      style={{ position: "relative", width: "100%", maxWidth: 400 }}
    >
      <input
        id={id}
        ref={inputRef}
        type="text"
        placeholder={placeholder}
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onFocus={() => setFocused(true)}
        onBlur={() => {
          setFocused(false);
          // Hide dropdown on blur only if invalid input or empty
          if (!isValid) {
            setShowDropdown(false);
            setHighlightedIndex(-1);
          }
        }}
        aria-autocomplete="list"
        aria-controls={listboxId}
        aria-expanded={showDropdown}
        aria-activedescendant={
          highlightedIndex >= 0
