Below is one example of a reusable Input component built with React and TypeScript. In this example the component accepts a list of options and shows a filtered dropdown that updates as the user types. If no options match the current input the dropdown will disappear. In addition, the component supports a custom validator so that if the input is invalid it displays a red border. (For huge lists, you could easily plug in a virtualization library such as react-window in the Dropdown; for brevity we show a simplified version.) 

Below is the full code:

--------------------------------------------------
/* Input.tsx */
import React, {
  useState,
  useMemo,
  useRef,
  useEffect,
  useCallback,
  ChangeEvent,
  KeyboardEvent,
} from 'react'

// Props interface: 
// • options: The complete list of suggestions.
// • value: The current value (if you want to control it externally).
// • onChange: Callback when the value changes.
// • validate: A function that returns true if the input is valid.
// • placeholder: Optional placeholder text.
interface InputProps {
  options: string[]
  value?: string
  onChange?: (value: string) => void
  validate?: (value: string) => boolean
  placeholder?: string
}

export const Input: React.FC<InputProps> = ({
  options,
  value = '',
  onChange,
  validate,
  placeholder = 'Type to search...',
}) => {
  const [inputValue, setInputValue] = useState<string>(value)
  const [isValid, setIsValid] = useState<boolean>(true)
  const [activeIndex, setActiveIndex] = useState<number>(-1)
  const containerRef = useRef<HTMLDivElement>(null)

  // Using useMemo to filter options based on input value.
  // You may debounce the input for extra performance on huge lists.
  const filteredOptions = useMemo(() => {
    const lowerInput = inputValue.toLowerCase().trim()
    if (!lowerInput) return []
    return options.filter((opt) =>
      opt.toLowerCase().includes(lowerInput)
    )
  }, [inputValue, options])

  // Handle clicks outside to close the dropdown.
  const handleClickOutside = useCallback(
    (evt: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(evt.target as Node)
      ) {
        setActiveIndex(-1)
      }
    },
    [containerRef]
  )

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside)
    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [handleClickOutside])

  // Input change handler with validation.
  const handleInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value
    setInputValue(val)
    // Validate using a provided function (if any) 
    if (validate) {
      setIsValid(validate(val))
    } else {
      setIsValid(true)
    }
    // If an onChange callback is passed, call it.
    if (onChange) {
      onChange(val)
    }
    // Reset active index for keyboard navigation.
    setActiveIndex(-1)
  }

  // When an option is selected from the dropdown.
  const handleOptionSelect = (option: string) => {
    setInputValue(option)
    if (onChange) {
      onChange(option)
    }
    // Option selected so dropdown closes.
    setActiveIndex(-1)
  }

  // Keyboard event handling: arrow navigation and enter selection.
  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (!filteredOptions.length) return

    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setActiveIndex((prev) =>
        prev < filteredOptions.length - 1 ? prev + 1 : 0
      )
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setActiveIndex((prev) =>
        prev > 0 ? prev - 1 : filteredOptions.length - 1
      )
    } else if (e.key === 'Enter') {
      e.preventDefault()
      if (activeIndex >= 0 && activeIndex < filteredOptions.length) {
        handleOptionSelect(filteredOptions[activeIndex])
      }
    } else if (e.key === 'Escape') {
      setActiveIndex(-1)
    }
  }

  return (
    <div ref={containerRef} style={{ position: 'relative', width: 300 }}>
      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        style={{
          width: '100%',
          padding: '8px',
          border: `1px solid ${isValid ? '#ccc' : 'red'}`,
          borderRadius: 4,
        }}
      />

      {/* Dropdown appears only if filtered options exist */}
      {filteredOptions.length > 0 && (
        <ul
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            right: 0,
            maxHeight: 200,
            overflowY: 'auto',
            listStyle: 'none',
            margin: 0,
            padding: 0,
            border: '1px solid #ccc',
            borderTop: 'none',
            backgroundColor: '#fff',
            zIndex: 1000,
          }}
        >
          {filteredOptions.map((option, index) => (
            <li
              key={option + index}
              onClick={() => handleOptionSelect(option)}
              onMouseEnter={() => setActiveIndex(index)}
              style={{
                padding: '8px',
                backgroundColor:
                  index === activeIndex ? '#f0f0f0' : '#fff',
                cursor: 'pointer',
              }}
            >
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

