Certainly! Using `AudioCapture` (the low-level audio capture interface provided by Unreal Engine) is a bit different than using `UAudioCaptureComponent`, as `AudioCapture` is more of a procedural audio capture interface, typically used for capturing raw audio data.

Below is a simple example showing how to use `AudioCapture` in your custom `AGameModeBase` subclass to capture audio input data and print the PCM buffer size to the log. This example shows how to:

- Create an `FAudioCapture` instance
- Start capturing audio
- Bind a delegate to receive captured audio buffer data

---

### Step 1: Enable the AudioCapture plugin

Make sure the **AudioCapture** plugin is enabled in your project (`Edit -> Plugins -> Audio`).

---

### Step 2: Include AudioCapture dependencies in your Build.cs

In your `YourProject.Build.cs`:

```csharp
PublicDependencyModuleNames.AddRange(new string[] {
    "Core",
    "CoreUObject",
    "Engine",
    "InputCore",
    "AudioCapture"  // Add this to enable AudioCapture module
});
```

---

### Step 3: Code example in your custom GameMode header and source files

**MyGameMode.h**

```cpp
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "AudioCapture.h"  // Include AudioCapture header
#include "MyGameMode.generated.h"

UCLASS()
class YOURPROJECT_API AMyGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    AMyGameMode();

    virtual void BeginPlay() override;
    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

private:

    // The low-level capture instance
    TUniquePtr<FAudioCapture> AudioCapture;

    // Callback function for receiving audio data
    void OnAudioCapture(const TArray<float>& AudioData, int32 NumChannels, int32 SampleRate, double StreamTime);

};
```

---

**MyGameMode.cpp**

```cpp
#include "MyGameMode.h"
#include "AudioCapture.h"

AMyGameMode::AMyGameMode()
{
    // Create the AudioCapture instance
    AudioCapture = MakeUnique<FAudioCapture>();
}

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    if (AudioCapture.IsValid())
    {
        // First, check if capture capability is available
        if (AudioCapture->Init())
        {
            // Bind the callback lambda or function to handle incoming audio
            AudioCapture->Start([this](const float* InAudioData, int32 InNumSamples, int32 InNumChannels, int32 InSampleRate, double StreamTime)
            {
                // Called in audio thread with new audio data

                // Copy sound data to a TArray (optional, for this example)
                TArray<float> AudioData;
                AudioData.Append(InAudioData, InNumSamples);

                // You might want to enqueue or handle in a thread-safe manner for further processing
                // For demonstration, just log the buffer size (on game thread)
                AsyncTask(ENamedThreads::GameThread, [this, AudioData, InNumChannels, InSampleRate, StreamTime]()
                {
                    OnAudioCapture(AudioData, InNumChannels, InSampleRate, StreamTime);
                });
            });

            UE_LOG(LogTemp, Log, TEXT("Audio capture started"));
        }
        else
        {
            UE_LOG(LogTemp, Warning, TEXT("Audio capture Init() failed"));
        }
    }
}

void AMyGameMode::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    // Stop and clean up capture when game ends
    if (AudioCapture.IsValid())
    {
        AudioCapture->Stop();
        AudioCapture.Reset();
    }

    Super::EndPlay(EndPlayReason);
}

void AMyGameMode::OnAudioCapture(const TArray<float>& AudioData, int32 NumChannels, int32 SampleRate, double StreamTime)
{
    // Example usage: log info about the captured audio buffer
    UE_LOG(LogTemp, Log, TEXT("Captured audio buffer: NumSamples=%d Channels=%d SampleRate=%d StreamTime=%.3f"), AudioData.Num(), NumChannels, SampleRate, StreamTime);
}
