using namespace std;

// A helper function to perform linear interpolation at a point "x".
// Given two vectors, x_original and y_original, we assume that the x‐values are sorted.
double linearInterpolate(double x, const vector<double>& x_original, const vector<double>& y_original) {
    int n = x_original.size();
    // Handle extrapolation on the left and right ends.
    if (x <= x_original.front()) {
        return y_original.front();
    }
    if (x >= x_original.back()) {
        return y_original.back();
