### How it works:
- The main app shows a vertical list of filenames.
- Each filename is shown with a delete button next to it.
- Clicking "Delete" removes the file UI entry.
- (No actual filesystem deletion for safety — just UI removal.)

---

### Code:

```python
from textual.app import App, ComposeResult
from textual.containers import Horizontal, Vertical
from textual.widgets import Button, Static
from textual.message import Message

class FileItem(Horizontal):
    """A horizontal container for a file label and a delete button."""

    class DeleteClicked(Message):
        """Message sent when the delete button is clicked."""
        def __init__(self, sender: "FileItem", filename: str) -> None:
            super().__init__(sender)
            self.filename = filename

    def __init__(self, filename: str):
        super().__init__()
        self.filename = filename

    def compose(self) -> ComposeResult:
        yield Static(self.filename, id="filename")
        yield Button("Delete", id="delete-btn")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        if event.button.id == "delete-btn":
            # Send message upward that delete was clicked
            self.post_message(self.DeleteClicked(self, self.filename))

class FileListApp(App):
    CSS = """
    Screen {
        align: center middle;
        padding: 1 2;
    }
    #file-list {
        border: round white;
        width: 60%;
        padding: 1 2;
    }
    FileItem {
        border: tall transparent;
        padding: 0 1;
        height: 3;
        content-align: center middle;
    }
    #filename {
        width: 1fr;
        content-align: left middle;
        padding-left: 1;
    }
    Button {
        dock: right;
        width: 10;
    }
    """

    def __init__(self, files: list[str]):
        super().__init__()
        self.files = files

    def compose(self) -> ComposeResult:
        with Vertical(id="file-list"):
            for filename in self.files:
                yield FileItem(filename)

    def on_file_item_delete_clicked(self, message: FileItem.DeleteClicked) -> None:
        # Remove the file from internal list
        if message.filename in self.files:
            self.files.remove(message.filename)
        # Remove widget from UI
        message.sender.remove()

if __name__ == "__main__":
    files = ["file1.txt", "report.pdf", "image.png", "data.csv"]
    app = FileListApp(files)
    app.run()
```

---

### Explanation:

- `FileItem` is a horizontal container widget with a `Static` label showing the filename, and a `Button` labeled "Delete".
- When the Delete button is clicked, `FileItem` sends a `DeleteClicked` message upwards to the app.
- `FileListApp` listens for the `DeleteClicked` message and removes the corresponding file from the list and UI.

