<script>
/**
 * A minimized prism syntax highlighting implementation for JavaScript, HTML, CSS.
 * This is a simplistic embedded version tailored only for highlight matching in this editor.
 */
var Prism=(function(){
  var langDefinitions = {
    javascript: {
      comment: /\/\/.*|\/\*[\s\S]*?\*\//g,
      string: /(["'`])(?:\\[\s\S]|(?!\1).)*\1/g,
      keyword: /\b(var|let|const|if|else|for|while|function|return|class|try|catch|finally|throw|await|async|new|this|typeof|instanceof|switch|case|break|default|import|from|export|extends|super|in|of)\b/g,
      number: /\b\d+\.?\d*(e[+-]?\d+)?\b/gi,
      boolean: /\b(true|false|null|undefined|NaN)\b/g,
      operator: /[+\-*/%=!<>|&^~?:]/g,
      punctuation: /[{}[\];(),.:]/g,
      regex: /\/(?:\\.|[^\/\r\n]+)\/[gimsuy]*/g,
      function: /\b\w+(?=\s*\()/g
    },
    html: {
      tag: /<\/?[^\s>\/]+(?:\s+[^\s=>\/]+(?:=(?:("[^"]*"|'[^']*'|[^\s'">=]+))?)?)*\s*\/?>/gi,
      comment: /<!--[\s\S]*?-->/g,
      attrName: /\b[a-zA-Z\-:]+(?==)/g,
      attrValue: /=("[^"]*"|'[^']*'|[^\s"'>]+)/g,
    },
    css: {
      comment: /\/\*[\s\S]*?\*\//g,
      atrule: /@[\w-]+[^{;]*;/g,
      selector: /[^\{\}\s][^\{\}]*?(?=\s*\{)/g,
      property: /\b[\w-]+(?=\s*:)/g,
      punctuation: /[{}:;]/g,
      value: /:\s*[^;]+;/g,
      important: /!important/g,
      number: /\b\d+(\.\d+)?(px|em|rem|%)?\b/g,
      string: /(["'])(?:\\.|(?!\1)[^\\\r\n])*\1/g
    }
  };

  function escapeHtml(str){
    return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  function matchAll(regex, str){
    let matches = [];
    let match;
    while((match = regex.exec(str)) !== null){
      matches.push({index: match.index, length: match[0].length, type: regex.type, text: match[0]});
      // Avoid zero length infinite loops
      if(match.index === regex.lastIndex){
        regex.lastIndex++;
      }
    }
    return matches;
  }

  // Sort matches by start index
  function sortMatches(matches){
    return matches.sort(function(a, b){return a.index - b.index;});
  }

  // Prism tokenize and highlight, simplified:
  function tokenize(text, language){
    if(language === 'none' || !langDefinitions[language]) {
      return escapeHtml(text);
    }
    const defs = langDefinitions[language];
    let allMatches = [];
    for(let type in defs){
      let regex = defs[type];
      // Attach type for matching
      if(typeof regex === 'function') continue;
      regex.lastIndex=0;
      regex.type = type;
      let matches = [];
      try{
        matches = matchAll(regex, text);
      }catch(e){matches=[];}
      allMatches = allMatches.concat(matches);
    }
    allMatches = sortMatches(allMatches);

    // Merge and build html:
    let result = '';
    let pos = 0;
    for(let i=0; i<allMatches.length; i++){
      let m = allMatches[i];
      if(m.index < pos) continue; // overlapping
      if(m.index > pos){
        result += escapeHtml(text.substring(pos, m.index));
      }
      let cls = 'token ' + m.type;
      let content = escapeHtml(m.text);
      result += `<span class="${cls}">${content}</span>`;
      pos = m.index + m.length;
    }
    if(pos < text.length){
      result += escapeHtml(text.substring(pos));
    }
    return result;
  }

  return {
    highlight: tokenize
  };
})();
</script>

