        const lines = selectedText.split('\n');
        let transformed = lines.map(line => '    ' + line).join('\n');
        editor.value = value.substring(0, start) + transformed + value.substring(end);
        editor.selectionStart = start;
        editor.selectionEnd = end + lines.length*4;
      } else {
