    findCurrentIndex++;
    if(findCurrentIndex >= findAllMatches.length) findCurrentIndex = 0;
    selectFindMatch(findCurrentIndex);
  }

  function findPrev(){
    if(findAllMatches.length === 0) return;
    findCurrentIndex--;
    if(findCurrentIndex < 0) findCurrentIndex = findAllMatches.length - 1;
    selectFindMatch(findCurrentIndex);
  }

