    updateAll();
    pushUndoStack(editor.value);

    // Reset and refind all matches because text changed
    performFindAll();
    if(findAllMatches.length === 0){
      findCurrentIndex = -1;
    } else if(findCurrentIndex >= findAllMatches.length){
      findCurrentIndex = 0;
    }
    selectFindMatch(findCurrentIndex);
  }

