    let startPos = editor.selectionStart;
    let lines = editor.value.substr(0, startPos).split('\n').length;
    const lineHeight = parseFloat(getComputedStyle(editor).lineHeight);
    const top = (lines - 1) * lineHeight;
    editor.scrollTop = top - lineHeight*2;
    syncScroll();
  }

  // Highlight with find matches
  function updateHighlightWithFind(){
    if(findAllMatches.length === 0){
