      if(i === findCurrentIndex) cls += ' current-highlight';
      frag += before + `<mark class="${cls}">${matchText}</mark>`;
      lastIndex = end;
    }
    frag += escapeHtml(text.substring(lastIndex));
    highlight.innerHTML = frag;
  }

  function escapeHtml(str){
    return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // Save file
  function saveToFile(){
    let ext = {
      javascript: '.js',
      html: '.html',
      css: '.css',
      none: '.txt'
    }[currentLanguage] || '.txt';
