  }

  function saveStateToStorage(){
    localStorage.setItem('advanced-notepad-content', editor.value);
    localStorage.setItem('advanced-notepad-language', currentLanguage);
  }

  // Event listeners
  editor.addEventListener('input', e => {
    if (ignoreInput) return;
    updateAll();
    pushUndoStack(editor.value);
    saveStateToStorage();
    performFindAll();
  });
  editor.addEventListener('scroll', syncScroll);
