  updateTheme();
  loadState();

  // CSS for find highlight
  const style = document.createElement('style');
  style.textContent = `
    mark.find-highlight {
      background: yellow;
      color: black;
      padding: 0;
      border-radius: 0;
    }
    mark.find-highlight.current-highlight {
      background: orange;
      color: black;
    }
