### `main.tf`

```hcl
provider "aws" {
  # Assume configured in root or provider block
}

# ECS Cluster (created or reused)
resource "aws_ecs_cluster" "this" {
  count = var.create_cluster ? 1 : 0

  name = var.ecs_cluster_name
}

data "aws_ecs_cluster" "existing" {
  count = var.create_cluster ? 0 : 1

  cluster_name = var.existing_cluster_name
}

locals {
  ecs_cluster_name = var.create_cluster ? aws_ecs_cluster.this[0].name : data.aws_ecs_cluster.existing[0].name
}

# IAM Role for ECS Task Execution
resource "aws_iam_role" "ecs_task_execution_role" {
  name = "${var.ecs_service_name}-execution-role"

  assume_role_policy = data.aws_iam_policy_document.ecs_task_execution_assume_role.json
}

data "aws_iam_policy_document" "ecs_task_execution_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Additional policy to allow SSM Parameter get (for token)
resource "aws_iam_policy" "ssm_get_parameter_policy" {
  name        = "${var.ecs_service_name}-ssm-get-parameter"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["ssm:GetParameter"]
      Resource = "arn:aws:ssm:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:parameter${var.token_ssm_parameter_name}"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_get_parameter_attachment" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = aws_iam_policy.ssm_get_parameter_policy.arn
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ECR repository (referencing existing)
data "aws_ecr_repository" "warp" {
  name = var.ecr_repo_name
}

# Task definition
resource "aws_ecs_task_definition" "warp" {
  family                   = var.ecs_service_name
  cpu                      = var.cpu
  memory                   = var.memory
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  execution_role_arn       = aws_iam_role.ecs_task_execution_role.arn
  task_role_arn            = aws_iam_role.ecs_task_execution_role.arn

  container_definitions = jsonencode([
    {
      name      = "warp"
      image     = "${data.aws_ecr_repository.warp.repository_url}:${var.image_tag}"
      essential = true
      portMappings = [
        {
          containerPort = 2408
          protocol      = "udp"
        }
      ]
      environment = [
        {
          name = "WARP_TOKEN"
          valueFrom = {
            "ssm" = var.token_ssm_parameter_name
          }
        }
      ]
      # Alternatively, ECS does not directly support environment variables from SSM.
      # One common method is to use AWS Parameter Store integration via AWS Secrets Manager or inject via task
      # To workaround, use secrets block instead:

      secrets = [
        {
          name      = "WARP_TOKEN"
          valueFrom = var.token_ssm_parameter_name
        }
      ]
    }
  ])
}

# Security Groups assignment must be passed in from outside (note: you could create it here if needed)

# ECS Service
resource "aws_ecs_service" "warp" {
  name            = var.ecs_service_name
  cluster         = local.ecs_cluster_name
  task_definition = aws_ecs_task_definition.warp.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets         = var.subnet_ids
    security_groups = var.security_group_ids
    assign_public_ip = true
  }

  depends_on = [aws_iam_role_policy_attachment.ecs_task_execution_policy]
}

# Simple delivery pipeline to fetch the latest ECR image and update ECS service
# Using CodePipeline and CodeBuild to deploy new image - example below

resource "aws_codepipeline" "warp" {
  count = var.codepipeline_enable ? 1 : 0

  name = "${var.ecs_service_name}-codepipeline"

  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = var.artifact_s3_bucket
    type     = "S3"
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = "CodeCommit"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = {
        RepositoryName = var.codecommit_repo_name
        BranchName     = var.codepipeline_branch_name
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      version          = "1"

      configuration = {
        ProjectName = aws_codebuild_project.warp_build.name
      }
    }
  }

  stage {
    name = "Deploy"

    action {
      name            = "Deploy"
      category        = "Deploy"
      owner           = "AWS"
      provider        = "ECS"
      input_artifacts = ["build_output"]
      version         = "1"

      configuration = {
        ClusterName = local.ecs_cluster_name
        ServiceName = aws_ecs_service.warp.name
        FileName    = "imagedefinitions.json"
      }
    }
  }
}

# CodePipeline and CodeBuild roles and policies

resource "aws_iam_role" "codepipeline_role" {
  count = var.codepipeline_enable ? 1 : 0

  name = "${var.ecs_service_name}-codepipeline-role"

  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json
}

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy_attachment" "codepipeline_policy_attach" {
  count      = var.codepipeline_enable ? 1 : 0
  role       = aws_iam_role.codepipeline_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodePipelineFullAccess"
}

resource "aws_codebuild_project" "warp_build" {
  count = var.codepipeline_enable ? 1 : 0

  name          = "${var.ecs_service_name}-build"
  service_role  = aws_iam_role.codebuild_role[0].arn
  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:5.0"
    type                        = "LINUX_CONTAINER"
    privileged_mode             = true
    environment_variable {
      name  = "ECR_REPO_NAME"
      value = var.ecr_repo_name
    }
  }

  source {
    type = "CODEPIPELINE"
    buildspec = <<EOF
version: 0.2

phases:
  pre_build:
    commands:
      - echo Logging in to Amazon ECR...
      - aws ecr get-login-password --region $AWS_DEFAULT_REGION | docker login --username AWS --password-stdin $AWS_ACCOUNT_ID.dkr.ecr.$AWS_DEFAULT_REGION.amazonaws.com
      - IMAGE_TAG=${var.image_tag}
  build:
    commands:
      - echo Build started on `date`
      - echo Build the Docker image...
      - docker build -t $ECR_REPO_NAME:$IMAGE_TAG .
      - docker tag $ECR_REPO_NAME:$IMAGE_TAG $AWS_ACCOUNT_ID.dkr.ecr.$AWS_DEFAULT_REGION.amazonaws.com/$ECR_REPO_NAME:$IMAGE_TAG
  post_build:
    commands:
      - echo Build completed on `date`
      - docker push $AWS_ACCOUNT_ID.dkr.ecr.$AWS_DEFAULT_REGION.amazonaws.com/$ECR_REPO_NAME:$IMAGE_TAG
      - printf '[{"name":"warp","imageUri":"%s.dkr.ecr.%s.amazonaws.com/%s:%s"}]' $AWS_ACCOUNT_ID $AWS_DEFAULT_REGION $ECR_REPO_NAME $IMAGE_TAG > imagedefinitions.json
artifacts:
  files: imagedefinitions.json
EOF
  }
}

resource "aws_iam_role" "codebuild_role" {
  count = var.codepipeline_enable ? 1 : 0

  name = "${var.ecs_service_name}-codebuild-role"

  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy_attachment" "codebuild_policy_attach" {
  count      = var.codepipeline_enable ? 1 : 0
  role       = aws_iam_role.codebuild_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryPowerUser"
}

resource "aws_iam_role_policy_attachment" "codebuild_ssm_access" {
  count = var.codepipeline_enable ? 1 : 0
  role  = aws_iam_role.codebuild_role[0].name 

  policy_arn = aws_iam_policy.ssm_get_parameter_policy.arn
}

# --------

# Output values
output "ecs_cluster_name" {
  value = local.ecs_cluster_name
}

output "ecs_service_name" {
  value = aws_ecs_service.warp.name
}

output "codepipeline_name" {
  value       = var.codepipeline_enable ? aws_codepipeline.warp[0].name : ""
  description = "CodePipeline name if created"
}
```

---

### Explanation: 

1. **Cluster**: Creates or reuses.  
2. **Task Definition**: Uses the ECR image, attaches the `WARP_TOKEN` from SSM Parameter Store via `secrets` (note: environment variables with SSM aren't supported directly, so use secrets block). The IAM role has permission to get parameter.  
