---

### Features implemented:
- Score tracking with tennis rules (points: 0, 15, 30, 40, Advantage).
- Up to 3 sets are tracked.
- UI to input points won by Player 1 or Player 2.
- Toggle to enable advanced point detail input.
- Store and show per-point details.

---

### How to use the code:
- Copy the code into a new SwiftUI project in Xcode.
- Run in the simulator or device.
- Tap the buttons for Player 1 or Player 2 to award points.
- Toggle "Show Advanced Point Details" to add details per point.
- See the full score and details update live.

---

```swift
import SwiftUI

// MARK: - Models

enum PointOutcome: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"

    var id: String { rawValue }
}

enum GamePoint: Int {
    case zero = 0, fifteen = 1, thirty = 2, forty = 3, advantage = 4

    func nextPoint() -> GamePoint? {
        switch self {
        case .zero: return .fifteen
        case .fifteen: return .thirty
        case .thirty: return .forty
        case .forty: return .advantage
        case .advantage: return nil
        }
    }

    func display() -> String {
        switch self {
        case .zero: return "0"
        case .fifteen: return "15"
        case .thirty: return "30"
        case .forty: return "40"
        case .advantage: return "Ad"
        }
    }
}

struct PointDetail: Identifiable {
    let id = UUID()
    let player: String
    let outcome: PointOutcome
    let timestamp: Date
}

struct Game {
    var p1Points: Int = 0
    var p2Points: Int = 0

    // Points stored as counts:
    // 0 = 0, 1 = 15, 2 = 30, 3 = 40, 4 = Ad
    // Will interpret in UI

    mutating func reset() {
        p1Points = 0
        p2Points = 0
    }
}

struct SetScore {
    var p1Games: Int = 0
    var p2Games: Int = 0

    mutating func reset() {
        p1Games = 0
        p2Games = 0
    }
}

class Match: ObservableObject {
    @Published var sets: [SetScore] = [SetScore(), SetScore(), SetScore()]
    @Published var currentSetIndex: Int = 0
    @Published var currentGame: Game = Game()

    // History of point details
    @Published var pointDetails: [PointDetail] = []

    // To track points within the game according to tennis rules:
    // We'll use integer raw points: 0 to 4, and advantage handled properly.

    // Returns the score string for current game
    func gameScoreDisplay() -> String {
        // Handle deuce and advantage logic
        let p1 = currentGame.p1Points
        let p2 = currentGame.p2Points

        if p1 >= 3 && p2 >= 3 {
            if p1 == p2 {
                return "Deuce"
            } else if p1 == p2 + 1 {
                return "Ad Player 1"
            } else if p2 == p1 + 1 {
                return "Ad Player 2"
            }
        }

        let p1Str = GamePoint(rawValue: p1)?.display() ?? "0"
        let p2Str = GamePoint(rawValue: p2)?.display() ?? "0"

        return "\(p1Str) - \(p2Str)"
    }

    // Add point to Player 1 or Player 2 with advanced detail
    func addPoint(to player: String, detail: PointOutcome? = nil) {
        // Update game score based on tennis rules
        if player == "Player 1" {
            updatePoints(&currentGame.p1Points, opponentPoints: &currentGame.p2Points)
        } else {
            updatePoints(&currentGame.p2Points, opponentPoints: &currentGame.p1Points)
        }

        // Add point detail if any
        if let outcome = detail {
            let newDetail = PointDetail(player: player, outcome: outcome, timestamp: Date())
            pointDetails.append(newDetail)
        } else {
            // Log point without outcome if advanced details off
            let newDetail = PointDetail(player: player, outcome: .winner, timestamp: Date())
            pointDetails.append(newDetail)
        }

        // Check if game is over after adding point
        if isGameOver() {
            // Increment games in current set
            if player == "Player 1" {
                sets[currentSetIndex].p1Games += 1
            } else {
                sets[currentSetIndex].p2Games += 1
            }

            currentGame.reset()

            // Check if set is over
            if isSetOver() {
                if currentSetIndex < 2 {
                    currentSetIndex += 1
                } else {
                    // Match over (best of 3)
                    // Optionally handle match end state
                }
            }
        }
    }

    private func updatePoints(_ playerPoints: inout Int, opponentPoints: inout Int) {
        // Tennis scoring rules logic

        // Scores meaning:
        // 0:0 => no points
        // Usually pts follow: 0 (0), 1 (15), 2 (30), 3 (40), 4 (Ad)

        // Basic increment rules:
        if playerPoints < 3 {
            playerPoints += 1
            // if player points reach 4 - means advantage, which means game if opponent less than 3
            // But we will handle that below
        } else if playerPoints == 3 { // player at 40
            if opponentPoints < 3 {
                // player wins immediately
                playerPoints = 4 // advantage, but next step game over detects
            } else if opponentPoints == 3 {
                // Deuce -> player gets advantage
                playerPoints = 4
            } else if opponentPoints == 4 {
                // Opponent has advantage, so back to deuce
                opponentPoints = 3
            }
        } else if playerPoints == 4 { // player has advantage
            // Winning the point wins the game - handled in isGameOver func
            playerPoints = 4
        }
    }

    private func isGameOver() -> Bool {
        let p1 = currentGame.p1Points
        let p2 = currentGame.p2Points

        // Conditions for game win:
        // One player must have at least 4 points and 2 points more than opponent
        if p1 >= 4 || p2 >= 4 {
            if abs(p1 - p2) >= 2 {
                return true
            }
        }
        return false
    }

    private func isSetOver() -> Bool {
        let p1 = sets[currentSetIndex].p1Games
        let p2 = sets[currentSetIndex].p2Games

        // Player must have at least 6 games and 2 games more than opponent
        if (p1 >= 6 || p2 >= 6) && abs(p1 - p2) >= 2 {
            return true
        }
        return false
    }

    func matchScoreDisplay() -> String {
        var result = ""
        for (index, set) in sets.enumerated() {
            result += "Set \(index + 1): \(set.p1Games) - \(set.p2Games)\n"
        }
        return result
    }

    func resetMatch() {
        sets = [SetScore(), SetScore(), SetScore()]
        currentSetIndex = 0
        currentGame.reset()
        pointDetails.removeAll()
    }
}

// MARK: - Views

struct ContentView: View {
    @ObservedObject var match = Match()
    @State private var showAdvancedDetails = false
    @State private var selectedOutcomeP1: PointOutcome = .winner
    @State private var selectedOutcomeP2: PointOutcome = .winner

