                    }
                    .padding()
                }
                .padding()

                HStack(spacing: 20) {
                    VStack(spacing: 10) {
                        Text("Player 1")
                            .font(.headline)
                        Button(action: {
                            if showAdvancedDetails {
                                match.addPoint(to: "Player 1", detail: selectedOutcomeP1)
                            } else {
                                match.addPoint(to: "Player 1")
                            }
                        }) {
                            Text("Add Point")
                                .bold()
