Certainly! Below is a production-ready React Native component `ExpandableText` that:

- Renders the text in one line initially.
- If the text overflows beyond 1 line, adds a "See more" clickable link at the end.
- When "See more" is clicked, expands to show the full text with a "See less" link.
- Handles dynamic content, supports styling, and accessibility.
- Includes PropTypes and default props for reusability.

---

### ExpandableText Component

```jsx
import React, { useState, useCallback } from 'react';
import {
  Text,
  View,
  StyleSheet,
  TouchableOpacity,
  LayoutChangeEvent,
} from 'react-native';
import PropTypes from 'prop-types';

const ExpandableText = ({
  text,
  numberOfLines = 1,
  seeMoreText = 'See more',
  seeLessText = 'See less',
  textStyle,
  seeMoreStyle,
  containerStyle,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showSeeMore, setShowSeeMore] = useState(false);
  const [fullHeight, setFullHeight] = useState(0);
  const [limitedHeight, setLimitedHeight] = useState(0);
  const [measured, setMeasured] = useState(false);

  // Called when full text layout is calculated (no line limit)
  const onTextLayoutFull = useCallback(
    (e) => {
      const height = e.nativeEvent.layout.height;
      setFullHeight(height);
      setMeasured(true);
    },
    [setFullHeight, setMeasured]
  );

  // Called when limited text layout is calculated (with numberOfLines)
  const onTextLayoutLimited = useCallback(
    (e) => {
      const height = e.nativeEvent.layout.height;
      setLimitedHeight(height);
    },
    [setLimitedHeight]
  );

  // Determine if "See more" is needed by comparing heights
  React.useEffect(() => {
    if (measured) {
      if (fullHeight > limitedHeight) {
        setShowSeeMore(true);
      } else {
        setShowSeeMore(false);
      }
    }
  }, [measured, fullHeight, limitedHeight]);

  // Toggle expand/collapse
  const toggleExpanded = () => {
    setIsExpanded((prev) => !prev);
  };

  return (
    <View style={containerStyle}>
      {/* 
        Invisible full text to measure height without limit
        Using opacity: 0 and absolute positioning to prevent UI flicker
      */}
      {!measured && (
        <Text
          style={[styles.hiddenText, textStyle]}
          onLayout={onTextLayoutFull}
          numberOfLines={undefined} // no limit
        >
          {text}
        </Text>
      )}

      {/* 
        Invisible limited line text to measure height with numberOfLines limit 
      */}
      {!measured && (
        <Text
          style={[styles.hiddenText, textStyle]}
          onLayout={onTextLayoutLimited}
          numberOfLines={numberOfLines}
        >
          {text}
        </Text>
      )}

      {/* Visible text */}
      <Text
        style={textStyle}
        numberOfLines={isExpanded ? undefined : numberOfLines}
      >
        {text}
