fun main() {
    // Example input as defined by the problem statement.
    // You can replace this with any method of input.
    val word = readLine()!!

    // Step 1: Count frequency of each letter
    val frequency = IntArray(26)
    for (ch in word) {
        frequency[ch - 'a']++
    }

    // Step 2: Collect letter frequencies that are > 0 and sort in descending order.
    val freqList = frequency.filter { it > 0 }.sortedDescending()

    // Step 3: Calculate total pushes.
    // There are 8 keys (digits 2 to 9) so we have 8 letters in the cost 1 positions,
    // next 8 letters in cost 2 positions, etc.
    var totalPushes = 0L
    for ((i, freq) in freqList.withIndex()) {
        // Calculate cost multiplier = (i / 8) + 1 (0-indexed)
        val cost = (i / 8) + 1
        totalPushes += freq.toLong() * cost
    }

    // Print the minimum total pushes needed.
    println(totalPushes)
}
------------------------------------------------

