import SwiftUI
import AVFoundation

// MARK: - ViewModel
final class AudioRecorderViewModel: NSObject, ObservableObject, AVAudioRecorderDelegate {
    @Published var isRecording = false
    @Published var powerLevels: [Float] = Array(repeating: -160, count: 5) // For 5 bars

    private var audioRecorder: AVAudioRecorder?
    private var levelTimer: Timer?

    private let numberOfBars = 5

    override init() {
        super.init()
    }

    func requestPermission() {
        AVAudioSession.sharedInstance().requestRecordPermission { granted in
            DispatchQueue.main.async {
                if !granted {
                    print("Microphone access denied.")
                }
            }
        }
    }

    func startRecording() {
        let session = AVAudioSession.sharedInstance()

        do {
            try session.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
            try session.setActive(true, options: .notifyOthersOnDeactivation)
            requestPermission()
        } catch {
            print("Failed to set up session: \(error.localizedDescription)")
            return
        }

        let url = getAudioFileURL()
        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC), // AAC encoded
            AVSampleRateKey: 44100,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
        ]

        do {
            audioRecorder = try AVAudioRecorder(url: url, settings: settings)
            audioRecorder?.delegate = self
            audioRecorder?.isMeteringEnabled = true
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()
            isRecording = true
            startMetering()
        } catch {
            print("Failed to start recording: \(error.localizedDescription)")
        }
    }

    func stopRecording() {
        audioRecorder?.stop()
        isRecording = false
        stopMetering()
        do {
            try AVAudioSession.sharedInstance().setActive(false, options: .notifyOthersOnDeactivation)
        } catch {
            print("Failed to deactivate session: \(error.localizedDescription)")
        }
    }

    private func getAudioFileURL() -> URL {
        let fileName = "recording_\(Date().timeIntervalSince1970).m4a"
        let documents = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        return documents.appendingPathComponent(fileName)
    }

    private func startMetering() {
        levelTimer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { [weak self] _ in
            guard let self = self, let recorder = self.audioRecorder, recorder.isRecording else {
                return
            }
            recorder.updateMeters()
            let newLevels = (0..<self.numberOfBars).map { _ in
                // averagePower(forChannel: 0) gives value between ~-160 and 0 (dB)
                // We'll generate some variance for the bars by adding randomness
                let basePower = recorder.averagePower(forChannel: 0)
                // Map the power to 0...1 for UI (invert dB range)
                let normalized = max(0, min(1, (basePower + 160) / 160))
                // Add minor random variation for nicer animation
                return Float(normalized * 100) * Float.random(in: 0.7...1.0)
            }
            DispatchQueue.main.async {
                self.powerLevels = newLevels
            }
        }
    }

    private func stopMetering() {
        levelTimer?.invalidate()
        levelTimer = nil
        // Reset powerLevels so bars go down smoothly
        DispatchQueue.main.async {
            self.powerLevels = Array(repeating: 0, count: self.numberOfBars)
        }
    }

    // MARK: AVAudioRecorderDelegate

    func audioRecorderDidFinishRecording(_ recorder: AVAudioRecorder, successfully flag: Bool) {
        if flag {
            print("Successfully finished recording. File saved at: \(recorder.url)")
        } else {
            print("Recording failed.")
        }
    }
