bool parseNumberString(const QString &input, int &result)
{
    QString s = input.trimmed().toLower();

    // Check binary format: 0b1010 or b1010
    QRegularExpression binaryRe("^(0b|b)([01]+)$");
    auto matchBinary = binaryRe.match(s);
    if (matchBinary.hasMatch()) {
        QString binStr = matchBinary.captured(2);
        bool ok = false;
        int val = binStr.toInt(&ok, 2);
        if (!ok) return false;
        result = val;
        return true;
    }

    // Check hex format: 0x2a or 2ah or h2a
    QRegularExpression hexRe1("^0x([0-9a-f]+)$");    // 0x2a
    auto matchHex1 = hexRe1.match(s);
    if (matchHex1.hasMatch()) {
        bool ok = false;
        int val = matchHex1.captured(1).toInt(&ok, 16);
        if (!ok) return false;
        result = val;
        return true;
    }

    QRegularExpression hexRe2("^([0-9a-f]+)h$");     // 2ah
    auto matchHex2 = hexRe2.match(s);
    if (matchHex2.hasMatch()) {
        bool ok = false;
        int val = matchHex2.captured(1).toInt(&ok, 16);
        if (!ok) return false;
        result = val;
        return true;
    }

    // Octal formats: maybe prefixed with 0o or 0 (classic C-style)
    QRegularExpression octRe("^0o([0-7]+)$"); // 0o52
    auto matchOct = octRe.match(s);
    if (matchOct.hasMatch()) {
        bool ok = false;
        int val = matchOct.captured(1).toInt(&ok, 8);
        if (!ok) return false;
        result = val;
        return true;
    }

    // Classic octal with leading 0 but no 0o; must be careful not to treat 0 as octal always
    // We'll check if string starts with '0' but is longer than 1 and all digits 0-7
    if (s.startsWith('0') && s.length() > 1 && s.indexOf(QRegularExpression("[^0-7]")) == -1) {
        bool ok = false;
        int val = s.toInt(&ok, 8);
        if (!ok) return false;
        result = val;
        return true;
    }

    // Finally try to parse as decimal or float and convert to int if equal to integer value
    bool okFloat = false;
    double valDouble = s.toDouble(&okFloat);
    if (okFloat) {
        int valInt = static_cast<int>(valDouble);
        // Check if valDouble is an integer value
        if (qFuzzyCompare(valDouble, double(valInt))) {
            result = valInt;
            return true;
        }
    }

    return false;
