          selectFile(filename, li);
        };

        // Double click to open in editor
        li.ondblclick = () => {
          openTextEditor(filename);
        };

        ul.appendChild(li);
      });
      clearSelection();
    }

    function selectFile(filename, liElem) {
      // Deselect previous
      [...ul.children].forEach(li => li.classList.remove('selected'));
      liElem.classList.add('selected');
      selectedFile = filename;
      btnRename.disabled = false;
      btnDelete.disabled = false;
    }

    function clearSelection() {
      selectedFile = null;
      [...ul.children].forEach(li => li.classList.remove('selected'));
      btnRename.disabled = true;
      btnDelete.disabled = true;
    }

    btnNewFile.onclick = () => {
      let newName = prompt("Enter name for new file", "NewFile.txt");
      if(newName) {
        if(fileSystem.files[newName]) {
          alert('File already exists!');
          return;
        }
        fileSystem.files[newName] = "";
        refreshFileList();
      }
    };

    btnRename.onclick = () => {
      if(!selectedFile) return;
      let newName = prompt("Enter new name for file", selectedFile);
      if(newName && newName !== selectedFile) {
        if(fileSystem.files[newName]) {
          alert('File with that name already exists!');
          return;
        }
        fileSystem.files[newName] = fileSystem.files[selectedFile];
        delete fileSystem.files[selectedFile];
        refreshFileList();
      }
    };

    btnDelete.onclick = () => {
      if(!selectedFile) return;
      if(confirm(`Delete file "${selectedFile}"?`)) {
        delete fileSystem.files[selectedFile];
        refreshFileList();
      }
    };

    refreshFileList();

    return container;
  }

  // --- Text Editor App ---

  // To track opened files in editors
  const openEditors = new Map();

  function createTextEditorApp(filename = null) {
    const container = createElement('div', {class:'text-editor'});
    const toolbar = createElement('div', {class:'toolbar'});
    const btnSave = createElement('button', {}, "Save");
    const btnClose = createElement('button', {}, "Close");
    toolbar.append(btnSave, btnClose);
    container.appendChild(toolbar);

    const textarea = createElement('textarea', {spellcheck:false});
    container.appendChild(textarea);

    let currentFile = filename;

    if(currentFile && fileSystem.files[currentFile] !== undefined) {
      textarea.value = fileSystem.files[currentFile];
    } else {
      currentFile = null;
    }

    btnSave.onclick = () => {
      if(!currentFile) {
        let saveName = prompt("Enter filename to save as", "Untitled.txt");
        if(!saveName) return;
        if(fileSystem.files[saveName]) {
          if(!confirm('File exists, overwrite?')) return;
        }
        currentFile = saveName;
      }
      fileSystem.files[currentFile] = textarea.value;
      alert('File saved');
    };

    btnClose.onclick = () => {
      // Close the window (the parent window in DOM)
      const win = container.closest('.window');
      if(win) windowsContainer.removeChild(win);
    };

    return {container, currentFile};
  }

  // --- Open apps handler ---
  function openApp(appId, options = {}) {
    if(appId === 'explorer') {
      const content = createFileExplorerApp();
      createWindow('File Explorer', content, options);
    } else if(appId === 'editor') {
      const {container} = createTextEditorApp(null);
      createWindow('Text Editor', container, options);
    }
  }

  // Helper to open text editor for specific file
  function openTextEditor(filename) {
    const {container} = createTextEditorApp(filename);
    createWindow(`Text Editor - ${filename}`, container);
