To create character movement on arbitrary surfaces (cube, sphere, custom model) in Unity 2023, where the character orients (rotates) along the surface normal, you need to:

- Detect the surface normal beneath the character.
- Align the character’s "up" direction with the surface normal.
- Move the character along the surface plane (tangent to the surface).
- Optionally, handle gravity or manual grounding checks.

---

### Key steps overview:

1. **Raycast downward** to find the surface and its normal.
2. **Calculate a rotation** that aligns the character's up vector to the surface normal.
3. **Move the character forward relative to the surface tangent**, not world forward.
4. Optionally, use a **CharacterController** or Rigidbody for physics.

---

### Example Script (C#) — CharacterMovementOnSurface.cs

```csharp
using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class CharacterMovementOnSurface : MonoBehaviour
{
    public float speed = 5f;
    public float gravity = 9.81f;
    public float raycastDistance = 2f; // How far down to raycast

    private CharacterController controller;
    private Vector3 verticalVelocity; // For gravity effect

    void Start()
    {
        controller = GetComponent<CharacterController>();
    }

    void Update()
    {
        // 1. Raycast down from character position to find surface normal
        if (Physics.Raycast(transform.position, -transform.up, out RaycastHit hit, raycastDistance))
        {
            Vector3 surfaceNormal = hit.normal;

            // 2. Align the character's up direction with the surface normal
            Quaternion targetRotation = Quaternion.FromToRotation(transform.up, surfaceNormal) * transform.rotation;
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRotation, Time.deltaTime * 10f);

            // 3. Calculate movement direction relative to the surface plane
            Vector3 input = new Vector3(Input.GetAxis("Horizontal"), 0, Input.GetAxis("Vertical"));
            Vector3 right = Vector3.Cross(transform.up, transform.forward).normalized;
            Vector3 forward = Vector3.Cross(right, transform.up).normalized;

            Vector3 move = (forward * input.z + right * input.x).normalized;

            // 4. Apply gravity along surface normal direction
            verticalVelocity += -surfaceNormal * gravity * Time.deltaTime;

            if (controller.isGrounded)
            {
                verticalVelocity = Vector3.zero; // Reset gravity velocity on ground
            }

            Vector3 totalMove = move * speed + verticalVelocity;

            // Move character
            controller.Move(totalMove * Time.deltaTime);
        }
        else
        {
            // No ground detected below – optionally apply default gravity or do nothing
            verticalVelocity += Physics.gravity * Time.deltaTime;
            controller.Move(verticalVelocity * Time.deltaTime);
        }
    }
}
```

