```hlsl
Shader "Custom/TextureQuadExtrusion"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrude ("Extrusion Factor", Float) = 0.1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 200

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #pragma target 4.0

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrude;

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 vertex : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(4)]
            void geom(point v2g input[1], inout TriangleStream<g2f> triStream)
            {
                // Sample the texture alpha at this vertex's UV
                float4 texcol = tex2D(_MainTex, input[0].uv);

                // Discard fully transparent pixels early (alpha threshold 0.01)
                if (texcol.a < 0.01)
                    return;

                // Calculate quad corners in clip space
                // We'll create a quad centered around the original point expanded by extrusion factor

                // First, convert clip space position back to view space or world space for extrusion is complicated
                // But as a simplification, we'll extrude in screen space using clip space offsets

                // Calculate size of one pixel in clip space to extrude properly:
                // Approximate pixel size in clip space:
                // We can get the screen size via Unity built-in, but in geometry shader we don't have it directly.
                // Let's assume _Extrude is in NDC (normalized device coordinates) units.
                // For a real application, you might want to pass screen pixel size from C#

                float4 center = input[0].vertex;

                float extrude = _Extrude;

                float2 offsets[4] = {
                    float2(-extrude, -extrude),
                    float2(-extrude,  extrude),
                    float2( extrude,  extrude),
                    float2( extrude, -extrude)
                };

                for (int i = 0; i < 4; i++)
                {
                    g2f o;
                    // Offset the position in clip space XY by offsets[i]
                    o.vertex = center;
                    o.vertex.xy += offsets[i];
                    o.uv = input[0].uv + offsets[i] * 0.5; // Adjust uv a bit (optional)
                    triStream.Append(o);
                }

                triStream.RestartStrip();
            }

            fixed4 frag(g2f i) : SV_Target
            {
                fixed4 col = tex2D(_MainTex, i.uv);
                // Output texture color with alpha applied
                clip(col.a - 0.01); // discard transparent fragments again
