### How to Prepare Mesh in C# Script:

```csharp
// Example to create points for each texel in texture
void CreatePointsMesh(Texture2D tex, float width, float height)
{
    int w = tex.width;
    int h = tex.height;

    Vector3[] vertices = new Vector3[w * h];
    Vector2[] uvs = new Vector2[w * h];
    int[] indices = new int[w * h];

    for (int y = 0; y < h; y++)
    {
        for (int x = 0; x < w; x++)
        {
            int i = y * w + x;
            vertices[i] = new Vector3(x * width, y * height, 0);
            uvs[i] = new Vector2((float)x / w, (float)y / h);
            indices[i] = i;
        }
    }

    Mesh mesh = new Mesh();
    mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
    mesh.vertices = vertices;
    mesh.uv = uvs;
    mesh.SetIndices(indices, MeshTopology.Points, 0);

    GetComponent<MeshFilter>().mesh = mesh;
}
```

This way the geometry shader will receive one point per pixel and decide whether to emit a quad at that position based on texture alpha.

