            // Our input data – here we assume our mesh is made up of points.
            struct appdata
            {
                float3 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            // Vertex-to-geometry structure. We are passing along the clip‐space position and the UV.
            struct v2g
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            // Geometry-to-fragment structure.
            struct g2f
            {
                float4 vertex : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            // Vertex shader: transform the input position into clip space.
            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = UnityObjectToClipPos(float4(v.vertex, 1.0));
                o.uv = v.uv;
                return o;
            }

            /*
              Geometry shader: for each input point, sample _MainTex at the associated UV.
              If the sample’s alpha is above _AlphaThreshold then we output a quad (composed of two triangle strips)
              representing that “pixel” – with one edge extruded along z.

              This example uses a fixed small offset in clip space (pixelSize) to create the quad.
              The left–bottom two vertices are at the original depth while the right–top ones get an extra _Extrude offset.

              Note: The math below is demonstrative. In many cases you’ll want to compute quad vertex positions in world or view space
              so that the extrusion functions correctly with perspective.
            */
            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> triStream)
            {
                // Sample the texture at the provided UV.
                float4 sampleColor = tex2D(_MainTex, IN[0].uv);
                if (sampleColor.a < _AlphaThreshold)
                {
                    // Skip transparent pixels.
                    return;
                }

                // Choose a quad size. Here we use an arbitrary clip–space offset.
                // (You might wish to derive this from _MainTex_TexelSize or from screen-space computations.)
                float pixelSize = 0.02;

                // We start with our original clip-space position.
                float4 basePos = IN[0].vertex;

                // We define offsets for our quad.
                // We will output a quad where the lower two vertices are at base depth
                // and the upper two vertices are "extruded" along z (by _Extrude).
                float4 offsetBL = float4(-pixelSize, -pixelSize, 0, 0); // bottom left
                float4 offsetBR = float4( pixelSize, -pixelSize, 0, 0); // bottom right
                float4 offsetTR = float4( pixelSize,  pixelSize, _Extrude, 0); // top right extruded
                float4 offsetTL = float4(-pixelSize,  pixelSize, _Extrude, 0); // top left extruded

                g2f o;

                // Emit the first triangle.
                o.uv = IN[0].uv;
                o.vertex = basePos + offsetBL;
                triStream.Append(o);

                o.uv = IN[0].uv;
                o.vertex = basePos + offsetBR;
                triStream.Append(o);

                o.uv = IN[0].uv;
                o.vertex = basePos + offsetTR;
                triStream.Append(o);

                // Emit the second triangle.
                o.uv = IN[0].uv;
                o.vertex = basePos + offsetTR;
                triStream.Append(o);

                o.uv = IN[0].uv;
                o.vertex = basePos + offsetTL;
                triStream.Append(o);

                o.uv = IN[0].uv;
                o.vertex = basePos + offsetBL;
                triStream.Append(o);
            }

            // Fragment shader: simply sample _MainTex.
            fixed4 frag(g2f i) : SV_Target
            {
                fixed4 col = tex2D(_MainTex, i.uv);
                return col;
            }
            ENDCG
        }
    }
    FallBack "Diffuse"
}

---------------------------------------------------------------

How This Works

1. Input Assumption:
  • The mesh driving the shader is made of points (each point’s vertex position is “anchored” and its UV corresponds to a pixel location in _MainTex). 
  • (You might use a script to create a point cloud from a texture if you want one point per texel.)

2. In the vertex shader the world–space (or object–space) positions are transformed to clip space.

3. The geometry shader (with [maxvertexcount(6)] because we output two triangles, six vertices in total) reads each point and samples _MainTex.
   • If the pixel’s alpha is below the chosen threshold it “culls” the point.
   • Otherwise it builds a quad: two lower vertices at the original depth and two upper vertices “extruded” by _Extrude.

4. The fragment shader simply re–samples the texture for color.

Adjust the quad position math to suit your needs (for example, computing correct offsets in world space, view space, or screen–space to match your actual pixel size). Also, note that extruding in clip space is not ideal if you want uniform “depth” appearance across a scene with perspective. In that case you’d convert positions to view space and build your geometry before transforming back to clip space.

