    // Some asynchronous code that might reject or throw
    return await Promise.resolve("Async hello!");
  });

  if (resultAsync.success) {
    console.log("Value:", resultAsync.value);
  } else {
    console.error("Error:", resultAsync.error);
  }
})(); 

