const Vision2Page = (props) => {
  // For POST API calls on left pane
  const methods = [
    { name: "DetectObjects", endpoint: "/api/vision2/detectObjects", defaultRequest: { imageUrl: "" } },
    { name: "ClassifyImage", endpoint: "/api/vision2/classifyImage", defaultRequest: { imageUrl: "" } },
    { name: "FindPosition", endpoint: "/api/vision2/findPosition", defaultRequest: { imageUrl: "", target: "" } },
    // add more methods here as desired
  ];

  const [selectedMethod, setSelectedMethod] = useState(null);
  const [postUri, setPostUri] = useState("");
  const [postBody, setPostBody] = useState("");
  const [responseJson, setResponseJson] = useState("");
  const [mockResponseBody, setMockResponseBody] = useState(""); // For editable response to set as mock
  const [apiRequestUrl, setApiRequestUrl] = useState("");

  // Called when clicking a method button, sets defaults
  const selectMethod = (method) => {
    setSelectedMethod(method);
    setPostUri(method.endpoint);
    const body = JSON.stringify(method.defaultRequest, null, 2);
    setPostBody(body);
    setResponseJson("");
    setMockResponseBody("");
    setApiRequestUrl(`POST ${method.endpoint}`);
  };

  const sendPostRequest = async () => {
    try {
      const parsedBody = JSON.parse(postBody);
      const response = await fetch(postUri, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(parsedBody),
      });
      // Try parse as JSON, otherwise fallback to text
      let data;
      try {
        data = await response.json();
      } catch (e) {
        data = await response.text();
      }

      const dataStr = typeof data === "string" ? data : JSON.stringify(data, null, 2);
      setResponseJson(dataStr);
      setMockResponseBody(dataStr);
    } catch (err) {
