                ${methods.map(
                  (m) =>
                    html`<button
                      class="btn ${selectedMethod === m ? "btn-primary" : "btn-outline"}"
                      onClick=${() => selectMethod(m)}>
                      ${m.name}
                    </button>`
                )}
              </div>
            </div>

            ${selectedMethod &&
            html`
              <div style="flex-grow: 1; display:flex; flex-direction: column; gap: 10px; overflow-y: auto; margin-top: 15px;">
                <div>
                  <label class="form-label">Request URL</label>
                  <input
                    class="form-input"
                    type="text"
                    value=${postUri}
                    onInput=${(e) => setPostUri(e.target.value)}
                  />
                </div>
                <div style="flex:1; display:flex; flex-direction: column;">
                  <label class="form-label">Request JSON Body</label>
                  <textarea
                    class="form-input"
                    style="flex: 1; min-height: 150px; font-family: monospace;"
                    value=${postBody}
                    onInput=${(e) => setPostBody(e.target.value)}
