        <button type="submit" id="submitBtn" style="display:none;">Submit</button>
    </form>

    <div id="message"></div>

    <script>
        const steps = [
            { id: 'username', info: 'Choose a unique username with 4-12 characters.' },
            { id: 'email', info: 'Enter a valid email address.' },
            { id: 'password', info: 'Enter a strong password (min 6 characters).' },
            { id: 'fullname', info: 'Enter your full name.' },
        ];

        let currentStepIndex = 0;

