        const infoBox = document.getElementById('infoBox');
        const nextBtn = document.getElementById('nextBtn');
        const submitBtn = document.getElementById('submitBtn');
        const messageBox = document.getElementById('message');

        function setStep(index) {
            currentStepIndex = index;

            steps.forEach((step, i) => {
                const input = document.getElementById(step.id);
                if (i === index) {
                    input.disabled = false;
                    input.classList.add('active');
                    input.focus();
                } else {
                    input.disabled = true;
                    input.classList.remove('active');
                }
            });

            infoBox.textContent = steps[index].info;

            // Toggle buttons
            if (index === steps.length - 1) {
                nextBtn.style.display = 'none';
                submitBtn.style.display = 'inline-block';
            } else {
                nextBtn.style.display = 'inline-block';
                submitBtn.style.display = 'none';
            }

            messageBox.textContent = "";
        }

        function validateInput(id, value) {
            switch(id) {
                case 'username':
                    return value.length >= 4 && value.length <= 12;
                case 'email':
                    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
                case 'password':
                    return value.length >= 6;
                case 'fullname':
                    return value.trim().length > 0;
                default:
                    return false;
            }
        }

        nextBtn.addEventListener('click', () => {
            const currentField = steps[currentStepIndex];
            const input = document.getElementById(currentField.id);
            const value = input.value.trim();

            if (!validateInput(currentField.id, value)) {
                alert('Please provide valid input.');
                input.focus();
                return;
            }

            if (currentStepIndex < steps.length - 1) {
                setStep(currentStepIndex + 1);
            }
        });

        // Allow pressing Enter to go to next step as well
        form.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                if (currentStepIndex < steps.length - 1) {
                    nextBtn.click();
                } else {
                    submitBtn.click();
                }
            }
        });

        form.addEventListener('submit', async (e) => {
            e.preventDefault();

            // Validate last field
            const lastStep = steps[currentStepIndex];
            const input = document.getElementById(lastStep.id);
            const value = input.value.trim();

            if (!validateInput(lastStep.id, value)) {
                alert('Please provide valid input.');
                input.focus();
                return;
            }

            // Prepare data
            const data = {
                username: document.getElementById('username').value.trim(),
                email: document.getElementById('email').value.trim(),
                password: document.getElementById('password').value.trim(),
                fullName: document.getElementById('fullname').value.trim()
            };

            try {
                const response = await fetch('/api/UserRegistration', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(data)
                });

                if (response.ok) {
                    const json = await response.json();
                    messageBox.style.color = 'green';
                    messageBox.textContent = json.message;

                    // Optionally reset form
                    form.reset();
                    setStep(0);
                } else {
                    const err = await response.text();
                    messageBox.style.color = 'red';
                    messageBox.textContent = `Error: ${err}`;
                }
            } catch (error) {
                messageBox.style.color = 'red';
                messageBox.textContent = `Request failed: ${error}`;
            }
        });

        // Initialize first step
        setStep(0);
    </script>
</body>
</html>
```

---

## How This Works:

- The form has 4 inputs (username, email, password, fullname).
- Only one input is enabled at a time (`input.disabled` toggled).
- The active input gets a blue border and background via `.active` CSS class.
- Under the form inputs, the `#infoBox` shows instructions about what the user should do currently.
- User clicks **Next** or presses Enter to validate current field and move forward.
- On the last step, **Submit** button appears, which posts all data at once to backend API.
- On success, success message shows; fields reset and guidance restarts from field #1.

---

# Summary

This pattern provides a **guided process framework** where:

- Frontend controls navigation through steps.
- UI guides the user by enabling only the current input.
- Visual cues and instructions help the user complete each input.
- Backend consumes consolidated data and processes registration.

You can enhance this by adding:

- Animations on focus shifting.
- Better validation error messages inline.
- Accessibility improvements (aria-live regions, keyboard navigation).
- Support for resuming partially complete registrations.

