class Events {
  constructor() {
    // A map from eventName to array of subscriber callbacks
    this.subscribers = new Map();
  }

  /**
   * Subscribe to an event with a callback
   * @param {string} eventName 
   * @param {Function} callback 
   */
  subscribe(eventName, callback) {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, []);
    }
    this.subscribers.get(eventName).push(callback);
  }

  /**
   * Unsubscribe a callback from an event
   * @param {string} eventName 
   * @param {Function} callback 
   */
  unsubscribe(eventName, callback) {
    if (!this.subscribers.has(eventName)) return;

    const callbacks = this.subscribers.get(eventName);
    const index = callbacks.indexOf(callback);
    if (index !== -1) {
      callbacks.splice(index, 1);
    }

    if (callbacks.length === 0) {
      this.subscribers.delete(eventName);
    }
  }

  /**
   * Trigger one or multiple events and pass options args to callbacks
   * @param {string|string[]} eventNames  - event name or array of event names
   * @param  {...any} options  - arguments to forward to callbacks
   */
  trigger(eventNames, ...options) {
    if (typeof eventNames === 'string') {
      eventNames = [eventNames];
    }

    for (const eventName of eventNames) {
      if (!this.subscribers.has(eventName)) continue;

      // Call all subscribers of this event name with provided options
      for (const cb of this.subscribers.get(eventName)) {
        try {
          cb(...options);
        } catch (e) {
          console.error(`Error in callback for event "${eventName}":`, e);
        }
      }
    }
  }
}
```

