        // If the API returns a “total” value, store it.
        if (this.totalRows === null && data.total !== undefined) {
          this.totalRows = data.total;
        }
        // Append the new rows (assuming data.rows is an array)
        this.rows.push(...data.rows);
      } catch (error) {
        console.error("Error fetching rows:", error);
      } finally {
        this.loading = false;
      }
    }
