import { ref, onMounted } from 'vue';
import { useRowsStore } from '../stores/rows';

export default {
  name: 'InfiniteScrollingTable',
  setup() {
    const rowsStore = useRowsStore();
    const scrollContainer = ref(null);
    // The number of rows to fetch each time
    const count = 20;

    // Load initial rows.
    const loadInitialRows = async () => {
      if (rowsStore.rows.length === 0) {
        await rowsStore.fetchRows(0, count);
      }
    };

    // When the user scrolls near the bottom, load more rows.
    const handleScroll = () => {
      const container = scrollContainer.value;
      if (!container) return;

      // A threshold value in pixels. When the user is within this distance from the bottom of the container, load more.
      const scrollThreshold = 100;
      if (container.scrollHeight - container.scrollTop - container.clientHeight < scrollThreshold) {
        // Calculate the new starting index and fetch rows.
        rowsStore.fetchRows(rowsStore.rows.length, count);
      }
    };

    onMounted(() => {
      loadInitialRows();
    });

    return {
      scrollContainer,
      handleScroll,
      rowsStore
    };
  }
};
